package com.meetspace.cache; import com.meetspace.repository.*; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.boot.ApplicationRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration;
@Configuration public class IndexManager {private static final Logger log=LoggerFactory.getLogger(IndexManager.class); private final EmployeeRepository employees;private final RoomRepository rooms;private final EmployeeIndex employeeIndex;private final RoomIndex roomIndex;public IndexManager(EmployeeRepository e,RoomRepository r,EmployeeIndex ei,RoomIndex ri){employees=e;rooms=r;employeeIndex=ei;roomIndex=ri;}public void refreshAll(){employeeIndex.clear();employees.all().forEach(employeeIndex::put);roomIndex.clear();rooms.all().forEach(roomIndex::put);} @Bean ApplicationRunner indexes(){return args->{refreshAll();log.info("Application indexes initialized: employees={}, rooms={}",employeeIndex.size(),roomIndex.size());};}}